// Renders the morning message. Every section is a plugin's plain text; ALL markup
// is made here. Contract: 05_daily-briefing/docs/briefing-plugin-spec.md
//
// Upstream nodes are read BY NAME, never $input: other nodes sit between them and this one.

// Telegram renders this with parse_mode HTML and much of it is visitor-supplied.
// Escape all of it, or one stray '<' silently kills the whole message.
const esc = (v) => String(v ?? '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');
// Page paths go in <code>, or Telegram turns '/about' into a bot-command link.
const line = (v) => esc(v).replace(/(^|\s)(\/[^\s]*)/g, '$1<code>$2</code>');
const clip = (v, n) => {
  const s = String(v ?? '').trim();
  return s.length > n ? s.slice(0, n - 1) + '…' : s;
};

const I = '     ';
const II = '          ';
const SEP = ' · ';

// ---- items ----------------------------------------------------------------
// An item is plain text. A '\n' in it is the plugin's own layout: the first line
// is the item, the rest its detail. A long one-line '·' item is split here, one
// fact per line: short facts stay on the head, a page trail goes last.
const SHORT = 10;   // a fact this short rides on the head line
const PACK = 28;    // detail facts share a line up to this width
const TRAIL = 40;   // a page trail wraps at this width
const isTrail = (f) => f.includes(' → ');
const isPath = (f) => /^\/\S*$/.test(f);
const isTally = (facts) => facts.every((f) => /^\S+ \d+$/.test(f));

const wrapTrail = (f) => f.split(' → ').reduce((out, hop, i) => {
  const piece = i ? '→ ' + hop : hop;
  if (out.length && (out.at(-1) + ' ' + piece).length <= TRAIL) out[out.length - 1] += ' ' + piece;
  else out.push(piece);
  return out;
}, []);

const shape = (text) => {
  const raw = String(text ?? '');
  if (raw.includes('\n')) {
    const [head, ...rest] = raw.split('\n').map((s) => s.trim()).filter(Boolean);
    return { head: head || '', detail: rest.map((d) => [d]) };
  }
  const facts = raw.split(SEP).map((f) => f.trim()).filter(Boolean);
  const split = facts.length > 1 && !isTally(facts)
    && (raw.length > 56 || facts.some((f) => isTrail(f) || isPath(f)));
  if (!split) return { head: raw.trim(), detail: [] };
  const head = [facts[0]];
  const loose = [];
  const trails = [];
  for (const f of facts.slice(1)) {
    if (isTrail(f)) trails.push(f);
    else if (f.length <= SHORT && !isPath(f)) head.push(f);
    else loose.push(f);
  }
  const packed = loose.reduce((out, f) => {
    if (out.length && (out.at(-1) + SEP + f).length <= PACK) out[out.length - 1] += SEP + f;
    else out.push(f);
    return out;
  }, []);
  // detail is a list of facts, each one or more lines (a wrapped trail is one fact)
  return { head: head.join(SEP), detail: [...packed.map((p) => [p]), ...trails.map(wrapTrail)] };
};

// `lines` caps an item's detail lines (only ever lowered inside a collapsed box, to fit).
const renderItem = ({ head, detail }, lines = Infinity) => {
  // A parenthesised item is a footnote: italic, no bullet.
  if (!detail.length && /^\(.*\)$/.test(head)) return `<i>${line(head.slice(1, -1))}</i>`;
  const all = detail.flat();
  const kept = all.slice(0, lines).map((d) => II + line(d));
  if (all.length > kept.length) kept.push(`${II}<i>… +${all.length - kept.length} more</i>`);
  return [`${I}• ${line(head)}`, ...kept].join('\n');
};

// Tall records get air between them; short lists stay tight.
// `fit` = { items, lines }: how much of a collapsed list is shown. Nothing is cut silently.
const FULL = { items: Infinity, lines: Infinity };
const renderItems = (items, airy, fit = FULL) => {
  const shaped = items.slice(0, fit.items).map(shape);
  const gap = airy || shaped.some((s) => s.detail.length >= 3) ? '\n\n' : '\n';
  const more = items.length - shaped.length;
  return shaped.map((s) => renderItem(s, fit.lines)).join(gap) + (more > 0 ? `\n<i>… +${more} more</i>` : '');
};

// 'Pages (visitors per page, no bots)' → bold name, italic qualifier.
const heading = (h) => {
  const m = /^(.*?)\s*(\(.*\))$/.exec(String(h));
  return m ? `▸ <b>${esc(m[1])}</b> <i>${esc(m[2])}</i>` : `▸ <b>${esc(h)}</b>`;
};
const renderBlock = (b, fit = FULL) => (b.heading ? heading(b.heading) + '\n' : '') + renderItems(b.items, false, fit);
// Blocks are separated by a blank line; a headingless first block hangs right under its header.
const renderBody = (blocks, fit = FULL) => {
  if (!blocks.length) return '';
  return (blocks[0].heading ? '\n\n' : '\n') + blocks.map((b) => renderBlock(b, fit)).join('\n\n');
};

// 'APP · last 24h' → name + tail. A top-level section shouts its name; a cluster member does not.
const titleParts = (t) => {
  const [name, ...tail] = String(t || '').split(SEP);
  return { name: name.trim(), tail: tail.join(SEP) };
};
const sentence = (s) => s.charAt(0).toUpperCase() + s.slice(1).toLowerCase();
const header = (icon, title, member) => {
  const { name, tail } = titleParts(title);
  return `${icon || '•'} <b>${esc(member ? sentence(name) : name.toUpperCase())}</b>` + (tail ? SEP + esc(tail) : '');
};

const LEVELS = ['alert', 'main', 'detail'];
const levelOf = (b) => (LEVELS.includes(b.level) ? b.level : 'main');
const blocksOf = (p) => (Array.isArray(p.blocks) ? p.blocks : [])
  .filter((b) => b && Array.isArray(b.items) && b.items.length);

// ---- calendar -------------------------------------------------------------
const events = $('Get Today\'s Events').all().map((i) => i.json)
  // alwaysOutputData sends one empty item when there are no events
  .filter((ev) => ev.summary || ev.start);
const fmt = (d) => d.toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit', hour12: false });
const eventLines = events.map((ev) => {
  const start = ev.start?.dateTime || ev.start?.date || '';
  const end = ev.end?.dateTime || ev.end?.date || '';
  const when = start.includes('T') ? `${fmt(new Date(start))}-${fmt(new Date(end))}` : 'All day';
  return `${I}• ${esc(when)}  ${esc(ev.summary || '(no title)')}`;
});
const greeting = '☀️ <b>Good morning!</b>\n<i>Your day:</i>'
  + (eventLines.length ? '\n' + eventLines.join('\n') : ' No events today');

// ---- signups (inline member, not a subworkflow) ---------------------------
// ALWAYS renders: signing up GRANTS access on a shared provider key, so the running
// total is the number that decides whether anything needs doing.
const cutoff = Date.now() - 24 * 60 * 60 * 1000;
const fresh = (value) => {
  const t = Date.parse(value);
  return Number.isFinite(t) && t >= cutoff;
};
const signupRows = $('Get Signups').all().map((i) => i.json).filter((r) => r.email);
const freshSignups = signupRows.filter((r) => fresh(r.signup_timestamp));
const signups = {
  key: 'signups',
  icon: '🌱',
  title: `SIGNUPS · ${signupRows.length} on the free tier` + (freshSignups.length ? ` · ${freshSignups.length} new` : ''),
  summary: freshSignups.length ? `${freshSignups.length} new signup${freshSignups.length === 1 ? '' : 's'}` : '',
  blocks: freshSignups.length ? [{
    items: freshSignups.map((r) => {
      const name = [r.first_name, r.surname].filter(Boolean).join(' ').trim();
      return (name || r.email) + (r.use_case ? ' — ' + clip(r.use_case, 50) : '');
    }),
  }] : [],
  empty: 'nobody new',
};

// ---- plugins --------------------------------------------------------------
// Matching is by KEY, never by position: a plugin that threw comes back as an error
// item with no key, so a registry key missing from the results is a failure we can name.
const registry = $('Plugins').all().map((i) => i.json).filter((r) => r && r.enabled);
const returned = new Map(
  $('Run Plugin').all().map((i) => i.json).filter((p) => p && p.key).map((p) => [p.key, p]),
);
returned.set('signups', signups);
// Signups has no subworkflow, so its registry row lives here; it opens the PromptPotter cluster.
const ppCluster = registry.find((r) => r.cluster && r.cluster.key === 'promptpotter');
const entries = [...registry, ...(ppCluster ? [{ key: 'signups', order: 34, cluster: ppCluster.cluster }] : [])]
  .sort((a, b) => (a.order || 0) - (b.order || 0));

const actions = [];
const alerts = [];
for (const r of entries) {
  const p = returned.get(r.key);
  if (!p) {
    alerts.push(`Briefing section "${r.key}" is missing\nits plugin failed; check the executions`);
    continue;
  }
  for (const a of (Array.isArray(p.actions) ? p.actions : [])) {
    if (a && a.text && Array.isArray(a.buttons) && a.buttons.length) actions.push(a);
  }
  for (const b of blocksOf(p)) if (levelOf(b) === 'alert') alerts.push(...b.items);
}

// ---- keyboard -------------------------------------------------------------
// Every action is ONE row of the briefing's own inline keyboard: '✅ <short label>' and '🤖',
// then the menu. No message per action. This is Telegram's own reply_markup, for a raw
// sendMessage: the Telegram node cannot send it, because its keyboard is a static
// fixedCollection and n8n drops an expression put in its place (exec 14896). Until the
// briefing sends through an HTTP Request (it needs the bot token in a credential that
// HTTP Request can use), Send to Telegram carries the menu alone, statically.
// A tap drops its row and leaves the text alone (16_commitments-ledger `Redraw Keyboard`).
const LABEL = 26;
const bytes = (s) => [...String(s)].reduce((n, ch) => {
  const c = ch.codePointAt(0);
  return n + (c < 0x80 ? 1 : c < 0x800 ? 2 : c < 0x10000 ? 3 : 4);
}, 0);
// The action's own 'label', else its first facts that fit: 'TalkTalk · CHF 22.75'.
const shortLabel = (a) => {
  const facts = String(a.label || a.text).split(/ · | — /).map((f) => f.trim()).filter(Boolean);
  let out = clip(facts[0] || '?', LABEL);
  for (const f of facts.slice(1)) {
    if ((out + SEP + f).length > LABEL) break;
    out += SEP + f;
  }
  return out;
};
const button = (text, cb) => ({ text, callback_data: cb });
const MENU = [
  [button('📊 Expenses', 'briefing:expenses'), button('📚 Learning Notes', 'briefing:learning')],
  [button('🛍️ Deal Finder', 'briefing:deals'), button('🗂 Kanban', 'briefing:board'), button('❓ Help', 'briefing:help')],
];
// Telegram caps callback_data at 64 BYTES and rejects the ENTIRE keyboard for one bad
// button, so an action that does not fit is left out, and said.
let unsendable = 0;
const taskRows = [];
for (const a of actions) {
  if (!a.buttons.every((b) => b && b.label && b.cb && bytes(b.cb) <= 64)) { unsendable++; continue; }
  const label = shortLabel(a);
  taskRows.push(a.buttons.map((b, i) => {
    const glyph = String(b.label).trim().split(/\s+/)[0];
    return button(i === 0 ? glyph + ' ' + label : glyph, b.cb);
  }));
}
if (unsendable) alerts.push(`${unsendable} task button${unsendable === 1 ? '' : 's'} could not be sent\ncallback data over 64 bytes; shorten the task id`);
const replyMarkup = { inline_keyboard: [...taskRows, ...MENU] };

// ---- sections -------------------------------------------------------------
// A section whose `empty` is '' says nothing on a quiet day: it renders only its alerts.
const quiet = (p) => p.empty === '';
const collapsed = (text) => `<blockquote expandable>${text}</blockquote>`;

// One member's sub-section inside a cluster: every level but alert, nothing collapsed further
// (Telegram has no toggle inside a toggle). The whole box is collapsed, so `fit` applies.
const memberText = (r, fit) => {
  const p = returned.get(r.key);
  if (!p) return `⚠️ <b>${esc(sentence(String(r.key)))}</b> unavailable (see attention)`;
  const blocks = blocksOf(p).filter((b) => levelOf(b) !== 'alert');
  if (!blocks.length && quiet(p)) return '';
  return header(p.icon, p.title || r.key, true)
    + (blocks.length ? renderBody(blocks, fit) : `\n${I}• ${line(p.empty || 'Nothing to report')}`);
};

// Each section is rendered at a `fit`; only what sits inside a collapsed box ever shrinks.
const sectionsAt = (fit) => {
  const out = [];
  const seenClusters = new Set();
  for (const r of entries) {
    if (r.cluster && r.cluster.key) {
      if (seenClusters.has(r.cluster.key)) continue;
      seenClusters.add(r.cluster.key);
      const members = entries.filter((m) => m.cluster && m.cluster.key === r.cluster.key);
      const summary = members.map((m) => returned.get(m.key)?.summary).filter(Boolean).join(SEP);
      out.push(`${r.cluster.icon || '•'} <b>${esc(r.cluster.title || r.cluster.key)}</b>`
        + (summary ? `\n<i>${esc(summary)}</i>` : '')
        + '\n' + collapsed(members.map((m) => memberText(m, fit)).filter(Boolean).join('\n\n')));
      continue;
    }
    const p = returned.get(r.key);
    if (!p) {
      out.push(`⚠️ <b>${esc(String(r.key).toUpperCase())}</b> unavailable (see attention)`);
      continue;
    }
    const all = blocksOf(p);
    const main = all.filter((b) => levelOf(b) === 'main');
    const detail = all.filter((b) => levelOf(b) === 'detail');
    if (!main.length && !detail.length && quiet(p)) continue;
    let text = header(p.icon, p.title || r.key, false);
    if (p.summary) text += `\n<i>${esc(p.summary)}</i>`;
    if (!main.length && !detail.length) {
      text += `\n${I}• ${line(p.empty || 'Nothing to report')}`;
    } else {
      text += renderBody(main);
      if (detail.length) text += '\n' + (main.length ? '\n' : '') + collapsed(detail.map((b) => renderBlock(b, fit)).join('\n\n'));
    }
    out.push(text);
  }
  return out;
};

const attention = alerts.length ? `⚠️ <b>NEEDS ATTENTION</b>\n\n${renderItems(alerts, true)}` : '';

// Prices arrive as the price-checker's own finished section.
const priceSection = String($('Check Prices').first().json.priceSection || '').trim();

// ---- the limit ------------------------------------------------------------
// Telegram allows 4096 characters AFTER parsing the HTML, so that is what is measured:
// tags stripped, entities unescaped (JS length counts UTF-16 units, as Telegram does).
const LIMIT = 4096;
const visible = (h) => h.replace(/<[^>]*>/g, '')
  .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&amp;/g, '&');
const JOIN = '\n\n\n';
const compose = (parts) => parts.filter(Boolean).join(JOIN);

// Nothing is dropped silently. First the collapsed detail shrinks, step by step, each cut
// saying '… +N more'; only if the message still does not fit does the rest go out as a
// second message, cut at a section boundary.
const FITS = [FULL, { items: 8, lines: Infinity }, { items: 5, lines: 3 }, { items: 3, lines: 1 }, { items: 1, lines: 0 }];
let parts = [];
for (const fit of FITS) {
  parts = [greeting, attention, ...sectionsAt(fit), priceSection].filter(Boolean);
  if (visible(compose(parts)).length <= LIMIT) break;
}

// A single section over the limit by itself is split on line boundaries into pieces that
// each fit; a blockquote open at a cut is closed there and reopened in the next piece
// (every other tag opens and closes on one line).
const CONTINUED = '<i>Morning briefing, continued</i>';
const BUDGET = LIMIT - visible(CONTINUED).length - JOIN.length;
const pieces = (part) => {
  if (visible(part).length <= BUDGET) return [part];
  const out = [];
  let chunk = [];
  let open = false;
  for (const ln of part.split('\n')) {
    if (chunk.length && visible([...chunk, ln].join('\n')).length > BUDGET - 1) {
      out.push(chunk.join('\n') + (open ? '</blockquote>' : ''));
      chunk = open ? ['<blockquote expandable>'] : [];
    }
    chunk.push(ln);
    if (ln.includes('<blockquote')) open = true;
    if (ln.includes('</blockquote>')) open = false;
  }
  if (chunk.length) out.push(chunk.join('\n'));
  // A reopened blockquote sits on its own line above; join it to the line it opens.
  return out.map((p) => p.replace(/^<blockquote expandable>\n/, '<blockquote expandable>'));
};
const messages = [];
let current = [];
for (const part of parts.flatMap(pieces)) {
  const head = messages.length ? [CONTINUED] : [];
  if (current.length && visible(compose([...head, ...current, part])).length > LIMIT) {
    messages.push(compose([...head, ...current]));
    current = [];
  }
  current.push(part);
}
if (current.length) messages.push(compose([...(messages.length ? [CONTINUED] : []), ...current]));

// One item per message. The keyboard rides on the first, the briefing itself.
return messages.map((message, i) => ({ json: { message, ...(i ? {} : { reply_markup: replyMarkup }) } }));

// Briefing plugin registry — THE SEAM.
//
// Adding a morning section means adding one line here. Nothing else in this
// workflow changes: Run Plugin dispatches dynamically on workflowId, and
// Format Message renders whatever comes back by key.
//
// 'order' is message position. Telegram hard-caps at 4096 characters and cuts the
// TAIL; every plugin's alerts are lifted to the top whatever its order, so what sorts
// last is what can best afford to be cut.
//
// 'cluster' renders its members as ONE section: one header, one summary line, one
// collapsed box. Signups is a member too; its row lives in Format Message (order 34),
// because it has no subworkflow to run.
//
// 'enabled: false' is the kill switch — a misbehaving plugin is switched off in
// one place, with no nodes to unwire.
// date/tz ride on the registry item: the plugin trigger accepts passthrough, so
// whatever is emitted here IS the plugin's input. Named inputs on the trigger
// would strip every other field, which the task-tap path depends on.
const ctx = { date: $now.toFormat('yyyy-MM-dd'), tz: 'Europe/Zurich' };
const promptpotter = { key: 'promptpotter', icon: '🏺', title: 'PROMPTPOTTER' };

return [
  // Emails held back because the vision LLM's daily quota ran out; an alert until rerun.
  { json: { key: 'inbox', order: 15, workflowId: 'ID_STOPPED_EMAILS', enabled: true, ...ctx } },
  { json: { key: 'commitments', order: 20, workflowId: 'ID_COMMITMENTS', enabled: true, ...ctx } },
  // The app tells this one what its accounts did; nothing here asks the app.
  { json: { key: 'app', order: 35, workflowId: 'ID_ACCOUNT_TRAIL', enabled: true, cluster: promptpotter, ...ctx } },
  // Site forms: nothing pings when one is sent, so this section is the only
  // announcement a message or a newsletter signup gets.
  { json: { key: 'reach', order: 36, workflowId: 'ID_SITE_FORMS', enabled: true, cluster: promptpotter, ...ctx } },
  // Yesterday's site visitors, counted and judged by the bot detector off its own table.
  { json: { key: 'site', order: 38, workflowId: 'ID_BOT_DETECTOR', enabled: true, cluster: promptpotter, ...ctx } },
  // Defects sort last: their alert is already at the top, the rest is reference.
  { json: { key: 'upkeep', order: 60, workflowId: 'ID_UPKEEP_DIGEST', enabled: true, ...ctx } },
];
